const hoy = $now.startOf('day');

const dosDigitos = (n) => String(n).padStart(2, '0');

const partirFecha = (valor) => {
  if (Array.isArray(valor)) {
    const [a, m, d, hh, mm] = valor;
    return {
      fecha: a + '-' + dosDigitos(m) + '-' + dosDigitos(d),
      hora: dosDigitos(hh || 0) + ':' + dosDigitos(mm || 0)
    };
  }

  const texto = String(valor);
  const partes = texto.split('T');
  return {
    fecha: partes[0] || '',
    hora: partes[1] ? partes[1].substring(0, 5) : 'N/A'
  };
};

const out = [];

for (const item of $input.all()) {
  const data = item.json;
  let citas = [];

  if (Array.isArray(data)) {
    citas = data;
  } else if (Array.isArray(data.citas)) {
    citas = data.citas;
  } else if (Array.isArray(data.data)) {
    citas = data.data;
  } else if (data && (data.fechaInicio || data.fechaFin)) {
    citas = [data];
  }

  for (const c of citas) {
    if (!c.fechaInicio) continue;

    const { fecha, hora } = partirFecha(c.fechaInicio);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(fecha)) continue;

    const fechaCita = DateTime.fromISO(fecha, { zone: hoy.zone });
    if (!fechaCita.isValid) continue;

    const diasFaltantes = Math.round(fechaCita.diff(hoy, 'days').days);

    const esRangoValido = diasFaltantes === 1 || diasFaltantes === 2;
    const noEstaCancelada = c.estadoCita !== 'CANCELADA' && c.estadoR !== false;
    const tieneCorreo = c.usuario && c.usuario.email;

    if (esRangoValido && noEstaCancelada && tieneCorreo) {
      out.push({
        json: {
          ...c,
          diasFaltantes,
          fechaTexto: fecha,
          horaTexto: hora
        }
      });
    }
  }
}

return out;

const citas = $items("Normalizar Citas");
let listaPacientes = "";

citas.forEach((item) => {
  const c = item.json;
  const hora = c.horaTexto || 'N/A';
  const etiqueta = c.diasFaltantes === 1 ? 'Falta 1 día' : 'Faltan 2 días';
  listaPacientes += `<li><b>${c.usuario?.nombre || 'Paciente'}</b> - ${hora} (${etiqueta}, Sede: ${c.sede || 'N/A'})</li>`;
});

const htmlContent = `
  <h2>Reporte Diario de Recordatorios Enviados</h2>
  <p>Hola Lina,</p>
  <p>Se han enviado exitosamente los recordatorios por correo.</p>
  <h3>Resumen de Pacientes Notificados (${citas.length} en total):</h3>
  <ul>${listaPacientes || '<li>Ninguno</li>'}</ul>
  <p><i>Este es un mensaje automático generado por el flujo de n8n.</i></p>
`;

return [{ json: { htmlReporte: htmlContent, totalCitas: citas.length } }];
